class Board:
    BOX = "SPY"    # sky-blue, pink, yellow boxes

    def __init__(self, rows, key):
        self.rows, self.key = rows, key
        self.chains = self._chains()
        top = sorted((c for c in self.chains if c["upper"]), key=lambda c: (c["r"], c["c"]))
        self.rules = [(a, b) for a, b in zip(top, top[1:])
                      if a["r"] == b["r"] and b["c"] == a["c"] + 7 * a["n"] + 3
                      and rows[a["r"] + 3][b["c"] - 3:b["c"]] == "GGG"]
        low = sorted((c for c in self.chains if not c["upper"]), key=lambda c: c["r"])
        self.text, self.answer = low[0], low[1]
        self.cursor = self._cursor()

    def glyph(self, r, c):
        return self.key([self.rows[r + a][c:c + 5] for a in range(5)])

    def _chains(self):
        out = []
        for r in range(58):
            c = 0
            while c < 64:
                col = self.rows[r][c]
                if col not in self.BOX or (r and self.rows[r - 1][c] == col):
                    c += 1
                    continue
                e = c
                while e < 64 and self.rows[r][e] == col:
                    e += 1
                if (e - c) % 7 == 0 and self.rows[r + 6][c:e] == col * (e - c):
                    n = (e - c) // 7
                    out.append({"r": r, "c": c, "n": n, "colour": col, "upper": self.rows[r][0] == "g",
                                "glyphs": [self.glyph(r + 1, c + 1 + 7 * i) for i in range(n)]})
                c = e
        return out

    def _cursor(self):
        # top half of the white bracket: 3 rows above the box, from its first glyph column
        wr = next(r for r in range(64) if "W" in self.rows[r])
        wc = self.rows[wr].index("W")
        for ch in [self.answer] + [s for rule in self.rules for s in rule]:
            i, rest = divmod(wc - ch["c"] - 1, 7)
            if ch["r"] - 3 == wr and rest == 0 and 0 <= i < ch["n"]:
                return ch, i
        return None

    def pairs(self):
        return [(a["glyphs"], b["glyphs"]) for a, b in self.rules]

