class Cycle:
    """What down (2) does to each glyph, learned from the board; up (1) is the reverse."""
    def __init__(self):
        self.down, self.up = {}, {}

    def see(self, before, after, move):
        if before != after:
            a, b = (before, after) if move == "2" else (after, before)
            self.down[a], self.up[b] = b, a

    def route(self, a, b):
        best = None
        for move, table in (("2", self.down), ("1", self.up)):
            x, k = a, 0
            while x != b and x in table and k < 6:
                x, k = table[x], k + 1
            if x == b and (best is None or k < len(best)):
                best = [move] * k
        return best

