def walk(n, start, todo):
    # BFS over (cursor, boxes still to visit) on a ring of n boxes
    todo = frozenset(todo) - {start}
    prev = {(start, todo): None}
    q = deque([(start, todo)])
    while q:
        s = q.popleft()
        if not s[1]:
            moves = []
            while prev[s]:
                s, m = prev[s]
                moves.append(m)
            return moves[::-1]
        for m, d in (("4", 1), ("3", -1)):
            p = (s[0] + d) % n
            t = (p, s[1] - {p})
            if t not in prev:
                prev[t] = (s, m)
                q.append(t)

