class RuleSearch:
    def __init__(self, side_glyphs, text, answer, mode):
        self.S, self.text, self.ans, self.mode = side_glyphs, text, answer, mode
        self.found = []

    def passes(self, k, s, test):
        g = shift(self.S[k], s)
        return g is not None and test(g)

    def options(self, k, fix, ban, test):
        if k in fix:
            return [fix[k]] if self.passes(k, fix[k], test) else []
        return [s for s in SHIFTS if s not in ban.get(k, ()) and self.passes(k, s, test)]

    def forbid(self, k, fix, ban, test):
        if k in fix:
            return None if self.passes(k, fix[k], test) else ban
        bad = {s for s in SHIFTS if self.passes(k, s, test)}
        if bad:
            ban = {**ban, k: set(ban.get(k, ())) | bad}
            if len(ban[k]) == 7:
                return None
        return ban

    def first_rule(self, test, fix, ban):
        for q in range(len(self.S) // 2):
            for s in self.options(2 * q, fix, ban, test):
                yield q, {**fix, 2 * q: s}, ban
            ban = self.forbid(2 * q, fix, ban, test)
            if ban is None:
                return

    def write(self, k, fix, ban, j):
        n = len(self.S[k])
        for s in self.options(k, fix, ban, lambda g: g == self.ans[j:j + n]):
            yield {**fix, k: s}, ban, j + n

    def output(self, q, fix, ban, j):
        k = 2 * q + 1
        if self.mode == "plain":
            yield from self.write(k, fix, ban, j)
            return
        for s in ([fix[k]] if k in fix else [s for s in SHIFTS if s not in ban.get(k, ())]):
            R = shift(self.S[k], s)
            if R is None:
                continue
            if self.mode == "twice":
                for p, f2, b2 in self.first_rule(lambda g: g == R, {**fix, k: s}, ban):
                    yield from self.write(2 * p + 1, f2, b2, j)
            else:
                yield from self.each(R, 0, {**fix, k: s}, ban, j)

    def each(self, R, t, fix, ban, j):
        if t == len(R):
            yield fix, ban, j
            return
        for p, f2, b2 in self.first_rule(lambda g: g[0] == R[t], fix, ban):
            for f3, b3, j3 in self.write(2 * p + 1, f2, b2, j):
                yield from self.each(R, t + 1, f3, b3, j3)

    def run(self, i=0, j=0, fix=None, ban=None):
        fix, ban = fix or {}, ban or {}
        if i == len(self.text):
            if j == len(self.ans):
                full = dict(fix)
                for k in range(len(self.S)):
                    full.setdefault(k, next(s for s in SHIFTS if s not in ban.get(k, ())))
                self.found.append(full)
            return self.found
        for q, f1, b1 in self.first_rule(lambda g: g == self.text[i:i + len(g)], fix, ban):
            for f2, b2, j2 in self.output(q, f1, b1, j):
                self.run(i + len(self.S[2 * q]), j2, f2, b2)
        return self.found

